import { tags } from "typia";

import { IShoppingMallSeller } from "./IShoppingMallSeller";

/**
 * Represents a single aggregated settlement row in a payment settlement report
 * for the shopping mall platform.
 *
 * Each row summarizes the financial settlement information for a grouping key
 * such as seller, period, or payout batch. It is designed for reporting and
 * reconciliation views, not for direct persistence. Values are expected to be
 * derived from underlying payment, refund, chargeback, and payout records.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPaymentSettlementReportRow = {
  /**
   * Unique identifier of the settlement report row.
   *
   * This is a technical identifier for the reporting system and may not
   * correspond directly to a primary key in a transactional table.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Seller associated with this settlement row.
   *
   * Provides high-level information about the seller whose transactions are
   * summarized in this row.
   */
  seller: IShoppingMallSeller.ISummary;

  /**
   * Inclusive start datetime of the settlement period for this row in ISO
   * 8601 format.
   */
  period_start: string & tags.Format<"date-time">;

  /**
   * Exclusive end datetime of the settlement period for this row in ISO 8601
   * format.
   */
  period_end: string & tags.Format<"date-time">;

  /**
   * ISO 4217 currency code in which all monetary values of this row are
   * expressed.
   *
   * Examples: "USD", "KRW", "EUR".
   */
  currency: string;

  /**
   * Total gross sales amount for the period before any discounts, refunds, or
   * fees.
   *
   * This includes the sum of all captured payment amounts for completed
   * orders associated with the seller in this period.
   */
  gross_sales_amount: number;

  /**
   * Total discounts applied to orders within the period.
   *
   * Includes promotional discounts, coupons, or other price reductions that
   * affect the seller’s receivable amount.
   */
  discount_amount: number;

  /**
   * Total amount refunded to customers within the period.
   *
   * This includes full and partial refunds that reduce the net amount payable
   * to the seller.
   */
  refund_amount: number;

  /**
   * Total monetary impact of chargebacks recognized in this period.
   *
   * Includes chargeback principal amounts and associated fees deducted due to
   * disputes resolved against the seller.
   */
  chargeback_amount: number;

  /**
   * Total platform service fees charged to the seller for this period.
   *
   * Typically includes commission fees, transaction fees, and any other
   * marketplace service fees.
   */
  platform_fee_amount: number;

  /**
   * Total tax amount withheld by the platform on behalf of the seller for
   * this settlement period.
   *
   * Used for tax reporting and compliance purposes.
   */
  tax_withheld_amount: number;

  /**
   * Net amount to be settled to the seller for this period.
   *
   * Calculated as gross sales minus discounts, refunds, chargebacks, platform
   * fees, and tax withholdings.
   */
  net_settlement_amount: number;

  /**
   * High-level status of the payout associated with this settlement row.
   *
   * Typical values may include:
   *
   * - "pending": Settlement calculated but not yet paid out
   * - "in_progress": Payout initiated and being processed
   * - "completed": Payout successfully transferred
   * - "failed": Payout attempt failed and requires attention
   */
  payout_status: string;

  /**
   * Reference code of the payout batch or payout transaction that will settle
   * or has settled this row.
   *
   * Useful for cross-referencing with payout statements, bank transfers, or
   * external settlement systems.
   */
  payout_reference_code?: string | undefined;

  /**
   * Datetime when this settlement report row was generated in ISO 8601
   * format.
   */
  generated_at: string & tags.Format<"date-time">;
};
